    "pgNoResults": "Aucun guide ne correspond. Essayez un autre mot ou posez directement votre question.",
    "pgFocusTitle": "Point clé",
    "pgUniversalNote": "Ces étapes valent dans la plupart des systèmes juridiques. Délais, frais et tribunaux compétents varient selon le pays ; vérifiez-les pour le vôtre.",
    "pgStepsTitle": "Étapes",
    "pgDeadlineCta": "Calculer un délai",
    "pgDocsTitle": "Documents à réunir",
    "pgLinksTitle": "Organismes officiels",
    "pgLinksFor": "Organismes officiels · {{country}}",
    "pgLinksHint": "Ces liens ouvrent des sites officiels. Les règles évoluent ; vérifiez-y les informations à jour.",
    "pgLinksNone": "Choisissez votre pays dans le conseiller pour voir les organismes officiels, ou posez votre question pour obtenir une réponse avec des sources officielles.",
    "pgLawyerTitle": "Quand consulter un avocat",
    "pgEmergency": "En danger ? Appelez le {{number}} maintenant",
    "pgEmergencyGeneric": "En danger ? Appelez maintenant le numéro d’urgence local.",
    "pgAskCta": "Demander comment ça marche dans mon pays",
    "pgAskTemplate": "{{title}} : comment cette démarche se déroule-t-elle dans mon pays ? Quelle autorité ou quel tribunal est compétent, quels délais s’appliquent et de quels documents ai-je besoin ?",
    "pgCaseCta": "Ouvrir un dossier pour cela",
    "pgShare": "Partager ce guide",
    "pgBack": "Tous les guides",
    "pgDisclaimer": "Information générale, pas un conseil juridique. NexuLex ne vous représente pas. Les lois, délais et frais varient selon les pays et évoluent ; vérifiez les sources officielles ou consultez un avocat avant d’agir.",
    "pgGroup_family": "Famille",
    "pgGroup_work": "Travail",
