    "pg_benefit_denied_focus": "يمكن الاعتراض على معظم قرارات الرفض. اطلب القرار كتابيًا وقدّم اعتراضك ضمن المهلة المحددة.",
    "pg_benefit_denied_lawyer": "إذا رُفض الاعتراض أو كان هناك نزاع حول التقييم الطبي.",
