    "pg_fine_appeal_focus": "تحقق في الإشعار من مهلة الاعتراض، ومما إذا كان الدفع المبكر يُعد إقرارًا بالمخالفة.",
    "pg_fine_appeal_lawyer": "نادرًا؛ فكّر فيه إذا كانت رخصتك أو عملك أو مبلغ كبير على المحك.",
    "guideNewProcessGuides": "جديد: أدلة خطوة بخطوة للمشكلات القانونية الشائعة مع الجهات الرسمية لكل بلد",
